#!/usr/bin/env bash
# a52xq (SM-A5260 / Galaxy A52 5G) + 官方 SukiSU Ultra —— builtin 线（non-GKI 4.19 专用）
# 用法: curl -fsSL <本脚本URL> | bash
set -euo pipefail

DRIVER_SHA=ce75122bec7423e0f1fa06e3e9a174085c5231ab   # builtin 分支 head，UAPI=6，配官方管理器 v4.2.1-r1(41049)
W="$HOME/a52xq-build"
mkdir -p "$W/scripts" "$W/patches" "$W/out"
cd "$W"

echo "=== [1/8] 写入内嵌文件（官方 4.19 钩子补丁 + 两个适配脚本） ==="
echo ''  | base64 -d > patches/ksu_hooks_sukisu_4.19.patch
echo '' | base64 -d > scripts/strip_legacy_ksu_hooks.py
echo ''   | base64 -d > scripts/fix_sources_for_419.py
echo '' | base64 -d > scripts/fix_driver_419.py
python3 -m py_compile scripts/*.py
wc -c scripts/*.py patches/*.patch

echo "=== [2/8] 依赖 ==="
if command -v apt-get >/dev/null 2>&1; then
  sudo apt-get update -qq || true
  sudo apt-get install -y -qq flex bison bc libssl-dev libelf-dev zip unzip patch python3 git curl cpio xz-utils || true
fi

echo "=== [3/8] 内核源码（自带 clang-r383902 + GCC 10.3 工具链） ==="
if [ ! -d kernel ]; then
  git clone --depth 1 -b OneUI8-dev https://github.com/micr0softstore/samsung_android_kernel_a52xq.git kernel
fi

echo "=== [4/8] 拉官方 builtin 线驱动（UAPI=6，配官方管理器 v4.2.1-r1 = 41049） ==="
# 不要用 "目录已存在就跳过" —— 上一轮失败时留在树里的可能是 main 线驱动。一律重下整体替换。
ok=0
for u in "https://codeload.github.com/SukiSU-Ultra/SukiSU-Ultra/tar.gz/$DRIVER_SHA" \
         "https://api.github.com/repos/SukiSU-Ultra/SukiSU-Ultra/tarball/$DRIVER_SHA"; do
  if curl -fsSL -o sukisu.tar.gz "$u" && tar -tzf sukisu.tar.gz >/dev/null 2>&1; then ok=1; break; fi
done
[ "$ok" = 1 ] || { echo "[!] 驱动下载失败"; exit 1; }
rm -rf kernel/KernelSU && mkdir -p kernel/KernelSU
tar -xzf sukisu.tar.gz -C kernel/KernelSU --strip-components=1
test -d kernel/KernelSU/kernel || { echo "[!] 驱动目录缺失"; exit 1; }
# 4.19 没有 linux/static_call.h（5.10 才有）。驱动只在 >=5.10 的分支用它（kernel/include/ksu.h 里有 guard），
# 但这个头文件是无条件 include 的 —— 注释掉即可。
if [ -f kernel/KernelSU/kernel/kernel_includes.h ]; then
  sed -i 's|^#include <linux/static_call\.h>.*|/* KSU-A52: 4.19 无 linux/static_call.h（5.10+），驱动仅在 >=5.10 分支使用 */|' kernel/KernelSU/kernel/kernel_includes.h
  echo "[i] static_call include 处理结果："
  grep -n 'static_call' kernel/KernelSU/kernel/kernel_includes.h || true
fi
# 4.19 里这两个头文件的位置不同，改 include（无匹配则什么都不做，安全幂等）
for f in $(grep -rl '<linux/hex\.h>' kernel/KernelSU/ 2>/dev/null || true); do
  sed -i 's|#include <linux/hex\.h>|#include <linux/kernel.h> /* KSU-A52: 4.19 无 linux/hex.h */|' "$f"
  echo "[i] hex.h -> kernel.h : $f"
done
for f in $(grep -rl '<uapi/linux/mount\.h>' kernel/KernelSU/ 2>/dev/null || true); do
  sed -i 's|#include <uapi/linux/mount\.h>|#include <linux/fs.h> /* KSU-A52: 4.19 无 uapi/linux/mount.h */|' "$f"
  echo "[i] uapi/linux/mount.h -> linux/fs.h : $f"
done
echo "--- 驱动 UAPI 常量（builtin 线在 kernel/include/uapi/，main 线在根 uapi/） ---"
grep -rn 'KERNEL_SU_UAPI_VERSION,' kernel/KernelSU/ | head -5
UAPI_OK=0
if grep -rqE 'KERNEL_SU_UAPI_VERSION, *6 *\)' kernel/KernelSU/ 2>/dev/null; then UAPI_OK=1; fi
if grep -rq 'UAPI_VERSION = 6' kernel/KernelSU/ 2>/dev/null; then UAPI_OK=1; fi
[ "$UAPI_OK" = 1 ] || { echo "[!] 驱动 UAPI 不是 6 —— 与官方管理器 v4.2.1-r1(41049) 不匹配，终止"; exit 1; }
echo "[OK] builtin 线驱动就位（UAPI=6）"

# 官方 builtin 线驱动的 4.19 适配在【钩子补丁应用之后】统一做（见第 6 步末尾），
# 因为其中包含对 fs/exec.c 里补丁插入代码的修复。

echo "=== [5/8] 接入驱动 ==="
cd kernel
ln -sfn ../KernelSU/kernel drivers/kernelsu
grep -q kernelsu drivers/Makefile || printf '\nobj-$(CONFIG_KSU) += kernelsu/\n' >> drivers/Makefile
if [ -f KernelSU/kernel/Kconfig ]; then
  grep -q 'drivers/kernelsu/Kconfig' drivers/Kconfig || sed -i '/^endmenu/i source "drivers/kernelsu/Kconfig"' drivers/Kconfig
fi
ls -l drivers/kernelsu/ | head -5

echo "=== [6/8] 清旧钩子 -> 打官方 4.19 钩子补丁 -> 4.19 适配 ==="
python3 "$W/scripts/strip_legacy_ksu_hooks.py" .
patch -p1 --forward -F3 < "$W/patches/ksu_hooks_sukisu_4.19.patch" || echo "[!] 钩子补丁有 hunk 未应用（继续，下面会校验符号）"
echo "--- 钩子符号清点 ---"
for f in fs/exec.c fs/open.c fs/read_write.c fs/stat.c drivers/input/input.c drivers/tty/pty.c; do
  printf '%-28s ksu 引用=%s\n' "$f" "$(grep -c 'ksu_' "$f" || true)"
done
python3 "$W/scripts/fix_sources_for_419.py" .
# 驱动 4.19 适配 + 【关键】fs/exec.c 里 sucompat(..., NULL, NULL, NULL) 的修复
# （实机崩溃栈：ksu_handle_execveat_sucompat+0xd0 <- do_execve+0x50 -> Kernel panic）
python3 "$W/scripts/fix_driver_419.py" KernelSU || { echo "[!] 驱动/钩子 4.19 适配失败"; exit 1; }
echo "--- fs/exec.c 的 sucompat 调用检查（必须无 NULL 传参） ---"
grep -n 'sucompat' fs/exec.c || true

echo "=== [6.5/8] SUSFS：内核补丁 + v2 API 兼容层 ==="
# SUSFS 是 SukiSU 的可选增强：隐藏 sus 挂载/路径、隐藏 ksu 符号、伪装 uname/cmdline、
# 伪装 AVC 日志。上游 4.19 分支停留在 v1.5.5，而 SukiSU 4.2.1 按 v2.x 接口调用，
# 故额外补 fs/susfs_compat_419.c 兼容层，并补齐 susfs_def.h 缺失的 v2 宏。
# 兼容层两文件随脚本分发：paste 直取，raw 作为兜底
fetch() { curl -fsSL --max-time 90 -o "$1" "$2" && return 0; curl -fsSL --max-time 90 -o "$1" "$3"; }
fetch "$W/scripts/apply_susfs_419.py" "https://paste.c-net.org/TextureZiegler" "https://raw.githubusercontent.com/Nahida5lp/a52xq-sukisu-kernel/main/scripts/apply_susfs_419.py"
fetch "$W/scripts/susfs_compat_419.c"  "https://paste.c-net.org/KnightZillion" "https://raw.githubusercontent.com/Nahida5lp/a52xq-sukisu-kernel/main/scripts/susfs_compat_419.c"
SUSFS_DIR="$W/.susfs4ksu"
rm -rf "$SUSFS_DIR"; mkdir -p "$SUSFS_DIR"
SUSFS_OK=0
for URL in \
  "https://gitlab.com/simonpunk/susfs4ksu/-/archive/kernel-4.19/susfs4ksu-kernel-4.19.tar.gz" \
  "https://gh-proxy.com/https://gitlab.com/simonpunk/susfs4ksu/-/archive/kernel-4.19/susfs4ksu-kernel-4.19.tar.gz" ; do
  echo "  下载 $URL"
  if curl -fsSL --max-time 300 -o "$SUSFS_DIR/s.tar.gz" "$URL"; then SUSFS_OK=1; break; fi
done
[ "$SUSFS_OK" = 1 ] || { echo "[!] SUSFS 下载失败"; exit 1; }
tar xzf "$SUSFS_DIR/s.tar.gz" -C "$SUSFS_DIR" --strip-components=1
grep -m1 'SUSFS_VERSION "' "$SUSFS_DIR/kernel_patches/include/linux/susfs.h" || true
python3 "$W/scripts/apply_susfs_419.py" . "$SUSFS_DIR" "$W/scripts" || { echo "[!] SUSFS 补丁应用失败"; exit 1; }
echo "--- SUSFS 落地检查 ---"
grep -n 'susfs' fs/Makefile || true
grep -c 'susfs' security/selinux/avc.c fs/susfs_compat_419.c 2>/dev/null || true
echo "--- susfs_def.h v2 宏检查（必须 3 个都有） ---"
for M in SUSFS_MAGIC CMD_SUSFS_ADD_SUS_PATH_LOOP CMD_SUSFS_ENABLE_AVC_LOG_SPOOFING; do
  printf '%-34s %s\n' "$M" "$(grep -c "$M" include/linux/susfs_def.h || true)"
done
echo "--- SUSFS 链接缺口检查（starts/ends 声明+实现、pty 死钩子） ---"
grep -c 'susfs_starts_with' include/linux/susfs.h fs/susfs_compat_419.c 2>/dev/null || true
grep -n 'SUSFS-HANDFIX:devpts-dead-hook' drivers/tty/pty.c || echo '[!] pty.c 的 ksu_handle_devpts 死钩子未移除'
echo "--- 驱动 event.c nofault 检查（裸 strncpy_from_user_nofault 必须 0） ---"
grep -c 'ksu_strncpy_from_user_nofault' KernelSU/kernel/sulog/event.c || true

echo "=== [6.6/8] SELinux 隐藏：4.19 后端 ==="
fetch "$W/scripts/apply_selinux_hide_419.py" "https://paste.c-net.org/BringinStrange" "https://raw.githubusercontent.com/Nahida5lp/a52xq-sukisu-kernel/main/scripts/apply_selinux_hide_419.py"
fetch "$W/scripts/selinux_hide_419.c" "https://paste.c-net.org/DiscountRamirez" "https://raw.githubusercontent.com/Nahida5lp/a52xq-sukisu-kernel/main/scripts/selinux_hide_419.c"
python3 "$W/scripts/apply_selinux_hide_419.py" . "$W/scripts" || { echo "[!] SELinux 隐藏后端应用失败"; exit 1; }
echo "--- SELinux 隐藏落地检查 ---"
grep -n 'ksu_selinux_fake_status_page' security/selinux/ss/status.c || true
for f in KernelSU/kernel/ksu_main.c KernelSU/kernel/ksu.c; do
  [ -f "$f" ] && grep -n 'selinux_hide_419\|ksu_selinux_hide_init' "$f" || true
done
echo "--- ksud.c 里 5.10 守卫残留（必须 0） ---"
grep -c 'KERNEL_VERSION(5, 10, 0)' KernelSU/kernel/runtime/ksud.c || true

# 硬断言：run #2 的 4 个 undefined reference 必须全部闭合，否则白等 18 分钟。
echo "--- 链接缺口硬断言（run #2 的 4 个 undefined reference） ---"
if grep -q 'ksu_handle_devpts((struct inode' drivers/tty/pty.c; then
  echo '[!] 致命：pty.c 仍调用无定义的 ksu_handle_devpts —— 链接必失败'; exit 1
fi
if ! grep -q 'bool susfs_starts_with' include/linux/susfs.h; then
  echo '[!] 致命：susfs.h 缺 susfs_starts_with 声明 —— 链接必失败'; exit 1
fi
for F in susfs_starts_with susfs_ends_with; do
  if ! grep -q "bool $F" fs/susfs_compat_419.c; then
    echo "[!] 致命：susfs_compat_419.c 缺 $F 实现 —— 链接必失败"; exit 1
  fi
done
if grep -qE '(^|[^_a-z])strncpy_from_user_nofault\(' KernelSU/kernel/sulog/event.c; then
  echo '[!] 致命：event.c 仍有裸 strncpy_from_user_nofault —— 4.19 链接必失败'; exit 1
fi
echo '[OK] 链接缺口已全部闭合 ✓'
echo ""

echo "=== [7/8] config + 编译 ==="
DEF=arch/arm64/configs/a52xq_defconfig
sed -i -E '/CONFIG_KSU_WITH_KPROBES/d' "$DEF"
for opt in KSU KSU_MANUAL_HOOK KSU_MANUAL_SU KPROBES KRETPROBES KALLSYMS KALLSYMS_ALL; do
  sed -i -E "/^# CONFIG_${opt} is not set$/d" "$DEF"
  sed -i -E "/^CONFIG_${opt}=/d" "$DEF"
done
{
  printf '\n# --- SukiSU Ultra builtin line (non-GKI 4.19), UAPI 6 ---\n'
  printf 'CONFIG_KSU=y\n'
  # SUSFS（需 [6.5/8] 应用内核补丁；SUS_MOUNT / SUS_MAP 不开，见 README）
  printf 'CONFIG_KSU_SUSFS=y\n'
  printf 'CONFIG_KSU_SUSFS_SUS_PATH=y\n'
  printf 'CONFIG_KSU_SUSFS_SUS_KSTAT=y\n'
  printf 'CONFIG_KSU_SUSFS_SPOOF_UNAME=y\n'
  printf 'CONFIG_KSU_SUSFS_ENABLE_LOG=y\n'
  printf 'CONFIG_KSU_SUSFS_HIDE_KSU_SUSFS_SYMBOLS=y\n'
  printf 'CONFIG_KSU_SUSFS_SPOOF_CMDLINE_OR_BOOTCONFIG=y\n'
  printf 'CONFIG_KSU_SUSFS_OPEN_REDIRECT=y\n'
  printf '# CONFIG_KSU_SUSFS_SUS_MOUNT is not set\n'
  printf '# CONFIG_KSU_SUSFS_SUS_MAP is not set\n'
  grep -q 'KSU_FEATURE_ADBROOT' KernelSU/kernel/Kconfig 2>/dev/null && printf 'CONFIG_KSU_FEATURE_ADBROOT=y\n' || true
  grep -q 'KSU_MANUAL_HOOK' KernelSU/kernel/Kconfig 2>/dev/null && printf 'CONFIG_KSU_MANUAL_HOOK=y\n' || true
  grep -q 'KSU_MANUAL_SU'   KernelSU/kernel/Kconfig 2>/dev/null && printf 'CONFIG_KSU_MANUAL_SU=y\n'   || true
  # 关键：绝对不要打开 CONFIG_KPROBES —— 三星 RKP/Knox 会因内核运行时改写代码段而 panic。
  # 实测证据：KPROBES=y 时内核能编过、能启动到锁屏，随后黑屏重启；
  # 而可正常启动的 tgk_v1.5.1 内核该项为 off。就这一项差异导致了 bootloop。
  printf 'CONFIG_KALLSYMS=y\nCONFIG_KALLSYMS_ALL=y\n# CONFIG_KPROBES is not set\n# CONFIG_KRETPROBES is not set\n'
  printf '# CONFIG_KPM is not set\n'
} >> "$DEF"
tail -14 "$DEF"
# 版本号固定，与官方管理器 v4.2.1-r1(41049) 对齐
if grep -q 'KSU_VERSION' KernelSU/kernel/Kbuild; then
  printf '\n# --- pinned ---\nccflags-y += -DKSU_VERSION=41049\nccflags-y += -DKSU_VERSION_FULL=\\"v4.2.1-r1-builtin@SukiSU-Ultra\\"\n' >> KernelSU/kernel/Kbuild
  grep -n 'KSU_VERSION' KernelSU/kernel/Kbuild | tail -4
fi
sed -i 's/-j16/-j$(nproc) -k/' build_kernel.sh
sed -i 's/^mkdir out$/mkdir -p out/' build_kernel.sh

# 【隐蔽性】抹掉构建环境痕迹。
# /proc/version 会原样暴露 KBUILD_BUILD_USER@KBUILD_BUILD_HOST，
# 用 GitHub Actions 编译时就是 `runner@runnervm8k3b6` —— 一眼就能看出是云端 CI 产物，
# 是可被检测模块（NativeCheck / Hunter 等）标记的弱信号。
# 这里改成中性值；如需伪装成特定值，设环境变量 KSU_BUILD_USER / KSU_BUILD_HOST 覆盖。
export KBUILD_BUILD_USER="${KSU_BUILD_USER:-android}"
export KBUILD_BUILD_HOST="${KSU_BUILD_HOST:-localhost}"
echo "--- /proc/version 构建身份: ${KBUILD_BUILD_USER}@${KBUILD_BUILD_HOST} ---"

# 【preinit / initrc 集成】默认【关闭】。
#
# 背景：驱动 Makefile 在解析阶段检查 $(objtree)/usr/include，不存在就定义 -DKSU_NO_PREINIT
# （关闭 preinit）。开着 preinit 时，模块 post-fs-data/service 阶段会由 init 上下文执行，
# 理论上更"正规"。
#
# 但实测结论（2026-10-25）：Zygisk Next 的 zygiskd 不能常驻，真正原因是模块目录里存在
# `disable` 标记（KernelSU 会完全跳过该模块的脚本），与 preinit 无关。删掉 disable 后
# 一切正常（zn-daemon / zn-nsdaemon-zygote* 都在跑）。
#
# 而开启 preinit 会要求 preinit runner 在 4.19 上能编译，目前有两个已知缺口：
#   1) nolibc/sys.h 的 __NR_vfork 在 runner 的头文件里未声明
#   2) nolibc/sys/mount.h 需要 5.x 才有的 <linux/mount.h>
# 所以这里默认不做 headers_install —— 回到"已验证可成功构建、可正常开机"的配置。
# 想试验 preinit 时：设 ENABLE_PREINIT=1 即可（失败时会在下面自动回退重试一次）。
PREINIT_MODE="${ENABLE_PREINIT:-0}"
if [ "$PREINIT_MODE" = "1" ]; then
  if ! grep -q 'headers_install' build_kernel.sh; then
    sed -i '0,/^[[:space:]]*make /{s//make -j$(nproc) ARCH=arm64 O=out headers_install INSTALL_HDR_PATH="$PWD\/out\/usr" >\/dev\/null 2>\&1 || true\n&/}' build_kernel.sh
    echo "--- 已注入 headers_install（ENABLE_PREINIT=1，preinit 前置步骤） ---"
  fi
else
  echo "--- preinit 保持关闭（默认，已验证的稳定配置）---"
fi
bash build_kernel.sh 2>&1 | tee "$W/out/build.log"
# 兜底：万一 preinit 路线把构建搞挂，强制 NO_PREINIT 再试一次，保证出包
if [ "$PREINIT_MODE" = "1" ] && [ ! -f out/arch/arm64/boot/Image ]; then
  echo "[!] 开启 preinit 的构建失败，强制 KSU_NO_PREINIT 重试一次 ---"
  sed -i 's/^\(\s*\)ccflags-y += -DKSU_NO_PREINIT/\1ccflags-y += -DKSU_NO_PREINIT/' KernelSU/kernel/Makefile 2>/dev/null || true
  printf '\n# --- 兜底：强制关闭 preinit ---\nccflags-y += -DKSU_NO_PREINIT\n' >> KernelSU/kernel/Makefile
  bash build_kernel.sh 2>&1 | tee -a "$W/out/build.log"
fi
ls -l out/arch/arm64/boot/Image
echo "--- /proc/version 泄漏自检（不应出现 runner@runnervm / codespace@ 之类 CI 标识） ---"
if strings out/arch/arm64/boot/Image 2>/dev/null | grep -m3 -E 'runner@|codespace|runnervm|actions@' ; then
  echo "[!] 警告：镜像里仍含 CI 构建者标识（见上）—— 隐蔽性不足"
else
  echo "[OK] 未发现 CI 构建者标识 ✓"
fi
echo "--- preinit 状态（默认关闭；见脚本顶部说明） ---"
grep -m3 -E 'preinit|KSU_NO_PREINIT' "$W/out/build.log" || echo "  (无 preinit 相关告警 ✓)"
grep -E '^CONFIG_(KSU|KSU_MANUAL_HOOK|KPROBES|KALLSYMS)' out/.config
# 硬断言：必须真的产出 Image，否则中止、不打包（避免"假成功"）
if [ ! -s out/arch/arm64/boot/Image ]; then
  echo "[!] 致命：out/arch/arm64/boot/Image 不存在或为空 —— 编译失败，中止，不打包"
  tail -40 "$W/out/build.log"
  exit 1
fi
echo "[OK] Image 已产出：$(stat -c %s out/arch/arm64/boot/Image) 字节"
# 硬断言：KPROBES 必须关闭（否则三星 RKP 会 panic、开机黑屏重启）
if grep -qE '^CONFIG_(KPROBES|KRETPROBES)=y' out/.config; then
  echo "[!] 致命：out/.config 里 CONFIG_KPROBES/KRETPROBES=y（会导致三星 RKP panic）—— 中止，不打包"
  exit 1
fi
echo "[OK] 已确认 KPROBES/KRETPROBES 关闭（与已验证可正常启动的 tgk config 一致）"
# 另一个硬断言：UAPI 必须是 6（配官方管理器 v4.2.1-r1 = 41049）
if ! grep -rqE 'KERNEL_SU_UAPI_VERSION, *6 *\)' KernelSU/kernel/include/uapi/supercall.h; then
  echo "[!] 致命：驱动 UAPI 版本不是 6 —— 中止"
  exit 1
fi
echo "[OK] UAPI=6 已确认"

echo "=== [8/8] 打包 TWRP 直刷 zip ==="
cp out/arch/arm64/boot/Image "$W/out/Image"
curl -fsSL -o "$W/tgk.zip" https://github.com/micr0softstore/samsung_android_kernel_a52xq/releases/download/Release_v1-5/tgk_v1.5.1_a52xq_sukisu.zip
rm -rf /tmp/pkg && mkdir -p /tmp/pkg && (cd /tmp/pkg && unzip -q "$W/tgk.zip")
cp out/arch/arm64/boot/Image /tmp/pkg/Image
sed -i 's/^kernel.string=.*/kernel.string=SukiSU Ultra v4.2.1-r1 builtin (UAPI 6)/' /tmp/pkg/anykernel.sh
sed -i 's/^ReSukiSU v4\.1\.0$/SukiSU Ultra v4.2.1-r1 builtin/' /tmp/pkg/version || true
(cd /tmp/pkg && zip -qr9 "$W/out/a52xq-sukisu-4.2.1-anykernel3.zip" .)
ls -l "$W/out/"

# 发布成 Release（Actions 用 GITHUB_WORKSPACE，Codespaces 用 /workspaces/<repo>）
GH_REPO_DIR="${GITHUB_WORKSPACE:-$(ls -d /workspaces/* 2>/dev/null | head -n1)}"
if command -v gh >/dev/null 2>&1 && [ -n "${GH_REPO_DIR:-}" ]; then
  TAG="kbuild-$(date +%m%d-%H%M%S)"
  ( cd "$GH_REPO_DIR" && gh release create "$TAG" \
      --title "a52xq SukiSU Ultra v4.2.1-r1 builtin UAPI6 ($TAG)" \
      --notes "built from micr0softstore/samsung_android_kernel_a52xq@OneUI8-dev + official SukiSU Ultra builtin line (UAPI 6) + official 4.19 manual hooks; pairs with official manager SukiSU_v4.2.1-r1_41049-release.apk" \
